std::mt19937 gen(std::random_device{}());
std::uniform_real_distribution<double> dist(-1.0, 1.0);
for (int i = 0; i < numberOfChecks; ++i) {
    double dx = dist(gen);
    double dy = dist(gen);
    double dz = dist(gen);
    double len = std::sqrt(dx*dx + dy*dy + dz*dz);
    if (len == 0.0) continue;
    double scale = 1e6;
    Point3d far(p.x() + dx/len*scale, p.y() + dy/len*scale, p.z() + dz/len*scale);
    int cnt = tree.numberIntersectedPrimitives(p, far);
    if (cnt % 2 == 1) return true;
}
return false;

